package main
import ("database/sql";"fmt";_ "github.com/jackc/pgx/v5/stdlib")
func main(){
 db,_:=sql.Open("pgx","postgres://eval_rw:eval_rw@postgres:5432/llmapi_eval")
 tx,_:=db.Begin()
 must:=func(q string,a ...any){ if _,err:=tx.Exec(q,a...);err!=nil{panic(err)} }
 must("UPDATE book SET price_cents=1200, stock=5 WHERE id=1")
 must("UPDATE book SET title='The Dispossessed' WHERE id=3")
 must("UPDATE book SET stock=10 WHERE id=4")
 must("DELETE FROM purchase_line WHERE purchase_id IN (9,10)")
 must("DELETE FROM purchase WHERE id IN (9,10)")
 if err:=tx.Commit();err!=nil{panic(err)}
 rows,_:=db.Query("select id,title,price_cents,stock,published from book where id in (1,3,4) order by id")
 for rows.Next(){var id,p,s int;var t string;var pub bool;rows.Scan(&id,&t,&p,&s,&pub);fmt.Println(id,t,p,s,pub)}
 var n int; db.QueryRow("select count(*) from purchase").Scan(&n); fmt.Println("purchases",n)
}
EOF
